const configuracao = {
  emitir_perguntas: true,
  api_feedback_habilitada: false,
  caminho_api_feedback: '',
  prazo_resposta_horas: 168,
  vinculos_slack_github: {},
  team_id: $env.APROVA_SLACK_TEAM_ID || '',
  app_id: $env.APROVA_SLACK_APP_ID || '',
  canal_id: $env.APROVA_SLACK_CANAL_CONSULTAS_ID || '',
};
const vinculosAmbiente = $env.SLACK_GITHUB_VINCULOS || '';
for (const par of vinculosAmbiente.split(',').map(v => v.trim()).filter(Boolean)) {
  const partes = par.split(':').map(v => v.trim());
  if (partes.length !== 2 || !/^[UW][A-Z0-9]+$/.test(partes[0]) ||
      !/^[A-Za-z0-9][A-Za-z0-9-]{0,38}$/.test(partes[1])) {
    throw new Error('SLACK_GITHUB_VINCULOS inválido; esperado USUARIO_SLACK:login_github.');
  }
  if (configuracao.vinculos_slack_github[partes[0]] &&
      configuracao.vinculos_slack_github[partes[0]].toLowerCase() !== partes[1].toLowerCase()) {
    throw new Error('Vínculo Slack/GitHub conflitante.');
  }
  configuracao.vinculos_slack_github[partes[0]] = partes[1];
}
return { json: {
  ...$json,
  configuracao_feedback: configuracao,
  rota_feedback: $json.slack ? 'resposta' : 'evento',
} };

const crypto = require('crypto');
const e = $json;
const cfg = e.configuracao_feedback;
const slack = e.slack;
if (e.meta?.assinatura_verificada !== true || slack?.type !== 'block_actions' ||
    slack.team?.id !== cfg.team_id || slack.api_app_id !== cfg.app_id ||
    slack.channel?.id !== cfg.canal_id ||
    typeof slack.user?.id !== 'string' || !/^[UW][A-Z0-9]+$/.test(slack.user.id)) {
  throw new Error('Resposta de feedback sem origem, workspace, app, canal ou usuário válidos.');
}
const recusar = motivo => ({ json: {
  ...e, feedback: { status: 'resposta_recusada', motivo },
  retorno_slack: { channel: cfg.canal_id, user: slack.user.id },
} });
const motivos = ['regra_conservadora', 'risco_aceito', 'falso_positivo'];
const acao = slack.actions?.[0];
if (!Array.isArray(slack.actions) || slack.actions.length !== 1 ||
    typeof acao?.action_id !== 'string' || typeof acao.value !== 'string' ||
    acao.value.length > 2000 || typeof acao.action_ts !== 'string' || !/^\d+\.\d+$/.test(acao.action_ts)) {
  return recusar('Interação de feedback inválida.');
}
const motivo = acao.action_id.replace(/^aprova_feedback_/, '');
if (!motivos.includes(motivo) || acao.action_id !== 'aprova_feedback_' + motivo) {
  return recusar('Motivo fora das três opções permitidas.');
}
const segredo = $env.N8N_SEGREDO_ACOES;
if (!segredo) return recusar('Configuração de assinatura indisponível; nada foi registrado.');
let token;
try { token = JSON.parse(acao.value); } catch { return recusar('Contexto do botão inválido.'); }
if (!token || typeof token !== 'object' || Array.isArray(token) ||
    typeof token.contexto !== 'string' || !/^[A-Za-z0-9_-]+$/.test(token.contexto) ||
    typeof token.assinatura !== 'string' || !/^[0-9a-f]{64}$/.test(token.assinatura)) {
  return recusar('Token de feedback inválido.');
}
const esperada = crypto.createHmac('sha256', segredo).update('aprova-feedback-v1.' + token.contexto).digest('hex');
if (!crypto.timingSafeEqual(Buffer.from(token.assinatura, 'hex'), Buffer.from(esperada, 'hex'))) {
  return recusar('Contexto adulterado; nada foi registrado.');
}
let c;
try { c = JSON.parse(Buffer.from(token.contexto, 'base64url').toString('utf8')); }
catch { return recusar('Contexto assinado inválido.'); }
const agora = Math.floor(Date.now() / 1000);
if (!c || typeof c !== 'object' || Array.isArray(c) || c.v !== 1 || c.feedback_reason !== motivo || c.team_id !== cfg.team_id ||
    c.app_id !== cfg.app_id || c.canal_id !== cfg.canal_id ||
    !Number.isSafeInteger(c.installation_id) || c.installation_id <= 0 ||
    !Number.isSafeInteger(c.id_aprovacao) || c.id_aprovacao <= 0 ||
    typeof c.task_run_id !== 'string' || !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(c.task_run_id) ||
    !Number.isSafeInteger(c.emitido_em) || !Number.isSafeInteger(c.expira_em) ||
    c.emitido_em > agora + 300 || c.expira_em <= agora || c.expira_em <= c.emitido_em ||
    c.expira_em - c.emitido_em > 720 * 3600) {
  return recusar('Contexto incompatível ou prazo expirado; nada foi registrado.');
}
const login = cfg.vinculos_slack_github[slack.user.id];
if (slack.user.id !== c.usuario_slack_esperado ||
    typeof login !== 'string' || typeof c.revisor_github !== 'string' ||
    login.toLowerCase() !== c.revisor_github.toLowerCase()) {
  return recusar('Somente o revisor que registrou esta aprovação pode informar o motivo.');
}
const pedido = {
  id_feedback: 'n8n:feedback:' + c.installation_id + ':' + c.id_aprovacao,
  installation_id: c.installation_id,
  id_aprovacao: c.id_aprovacao,
  task_run_id: c.task_run_id,
  usuario_slack: slack.user.id,
  workspace_slack: slack.team.id,
  feedback_reason: motivo,
};
return { json: {
  ...e, feedback: { status: 'resposta_validada', motivo: 'Resposta autenticada, ainda não persistida.',
    installation_id: c.installation_id, id_aprovacao: c.id_aprovacao,
    task_run_id: c.task_run_id, feedback_reason: motivo },
  pedido_feedback: pedido,
  retorno_slack: { channel: cfg.canal_id, user: slack.user.id },
} };

const crypto = require('crypto');
const cfg = $json.configuracao_feedback;
const caminho = cfg?.caminho_api_feedback;
const bloqueado = typeof caminho !== 'string' || !/^\/[A-Za-z0-9/_-]+$/.test(caminho) ||
  ['/acoes-remotas', '/health', '/ready', '/reports/weekly'].includes(caminho.replace(/\/+$/, '')) ||
  /^\/webhooks(?:\/|$)/.test(caminho);
if ($json.feedback?.status !== 'resposta_validada' || cfg.api_feedback_habilitada !== true || bloqueado) {
  throw new Error('Envio de feedback bloqueado: endpoint específico ainda precisa ser implementado e configurado.');
}
const segredo = $env.N8N_SEGREDO_ACOES;
if (!segredo) throw new Error('N8N_SEGREDO_ACOES indisponível.');
if (!$env.APROVA_API_URL) throw new Error('APROVA_API_URL indisponível.');
const corpo = JSON.stringify($json.pedido_feedback);
const timestamp = Math.floor(Date.now() / 1000).toString();
return { json: { ...$json, requisicao_feedback: {
  url: $env.APROVA_API_URL.replace(/\/+$/, '') + caminho,
  corpo,
  headers: {
    'X-Aprova-Timestamp': timestamp,
    'X-Aprova-Assinatura': 'sha256=' + crypto.createHmac('sha256', segredo).update(timestamp + '.').update(corpo).digest('hex'),
  },
} } };

const origem = $('10 | Validar Clique e Contexto').first().json;
const f = origem.feedback;
let status = f.status;
let mensagem;
if (status === 'resposta_recusada') {
  mensagem = f.motivo;
} else if (origem.configuracao_feedback.api_feedback_habilitada !== true ||
           !origem.configuracao_feedback.caminho_api_feedback) {
  status = 'pendente_api';
  mensagem = 'Seu motivo foi selecionado, mas NÃO foi registrado no núcleo. O endpoint de feedback ainda precisa ser implementado e habilitado. Tente novamente quando a integração estiver disponível.';
} else {
  const r = $json.body ?? $json.data;
  const pedido = origem.pedido_feedback;
  if ([200, 201].includes($json.statusCode) && r && typeof r === 'object' && !Array.isArray(r) &&
      r.status === 'registrado' && r.installation_id === pedido.installation_id &&
      r.id_aprovacao === pedido.id_aprovacao && r.feedback_reason === pedido.feedback_reason) {
    status = 'registrado';
    mensagem = 'Motivo registrado no núcleo: ' + ({
      regra_conservadora: 'Regra conservadora demais',
      risco_aceito: 'Risco aceito conscientemente',
      falso_positivo: 'Falso positivo',
    })[pedido.feedback_reason] + '. Obrigado pelo feedback.';
  } else {
    status = 'nao_confirmado';
    mensagem = 'O núcleo não confirmou a gravação do feedback. Nenhuma alteração de aprovação foi solicitada. Confira o resultado antes de reenviar.';
  }
}
return { json: { feedback: { ...f, status }, retorno_slack: origem.retorno_slack,
  texto_retorno: mensagem.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'),
} };

const origem = $('14 | Preparar Retorno do Feedback').first().json;
if ($json.ok !== true) throw new Error('Slack não confirmou o aviso ao usuário. Verifique a execução; isso não desfaz eventual gravação já confirmada pelo núcleo.');
return { json: { feedback: { ...origem.feedback, notificacao_slack: 'enviada' } } };

const f = $json.feedback;
if (!f || typeof f.status !== 'string') throw new Error('Resultado de feedback ausente.');
return { json: { feedback: {
  status: f.status,
  motivo: f.motivo || null,
  installation_id: f.installation_id || null,
  id_aprovacao: f.id_aprovacao || null,
  task_run_id: f.task_run_id || null,
  feedback_reason: f.feedback_reason || null,
  mensagem_slack_ts: f.mensagem_slack_ts || null,
  notificacao_slack: f.notificacao_slack || null,
  registrado_no_nucleo: f.status === 'registrado',
} } };

const e = $json;
const cfg = e.configuracao_feedback;
const resultado = (status, motivo, extra = {}) => ({ json: {
  ...e, feedback: { status, motivo, ...extra },
} });
if (e.meta?.origem_verificada !== true || e.meta?.validacao?.valido !== true) {
  throw new Error('Feedback exige evento autenticado e normalizado pelo Core.');
}
if (e.evento?.tipo !== 'aprovacao_registrada' || e.aprovacao?.decisao !== 'aprovada' ||
    e.risco?.nivel_original !== 'ALTO') {
  return resultado('ignorado', 'Somente aprovação registrada de risco original ALTO solicita motivo.');
}
const tenant = e.meta.tenant_id;
const aprovacao = e.aprovacao.id;
const analise = e.dados?.task_run_id || e.meta.execution_id;
const revisor = e.aprovacao.login_github;
const repositorio = e.repositorio?.full_name;
const numero = e.pr?.numero;
if (!Number.isSafeInteger(tenant) || tenant <= 0 || !Number.isSafeInteger(aprovacao) || aprovacao <= 0 ||
    typeof analise !== 'string' || !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(analise) ||
    typeof revisor !== 'string' || !/^[A-Za-z0-9][A-Za-z0-9-]{0,38}$/.test(revisor) ||
    typeof repositorio !== 'string' || !/^[A-Za-z0-9][A-Za-z0-9-]{0,38}\/[A-Za-z0-9._-]{1,100}$/.test(repositorio) ||
    !Number.isSafeInteger(numero) || numero <= 0) {
  throw new Error('Evento de aprovação sem instalação, aprovação, análise, revisor ou PR válidos.');
}
if (e.dados?.task_run_id && e.meta.execution_id && e.dados.task_run_id !== e.meta.execution_id) {
  throw new Error('Análise inconsistente no evento.');
}
const base = { installation_id: tenant, id_aprovacao: aprovacao, task_run_id: analise,
  revisor_github: revisor, repositorio, numero_pr: numero,
  chave: tenant + ':' + aprovacao };
if (!cfg.emitir_perguntas) return resultado('configuracao_pendente', 'Emissão de perguntas desabilitada.', base);
if (!/^T[A-Z0-9]+$/.test(cfg.team_id) || !/^A[A-Z0-9]+$/.test(cfg.app_id) ||
    !/^[CG][A-Z0-9]+$/.test(cfg.canal_id)) {
  return resultado('configuracao_pendente', 'Configure workspace, app e canal Slack no ambiente.', base);
}
const usuarios = Object.entries(cfg.vinculos_slack_github)
  .filter(([usuario, login]) => /^[UW][A-Z0-9]+$/.test(usuario) &&
    typeof login === 'string' && login.toLowerCase() === revisor.toLowerCase())
  .map(([usuario]) => usuario);
if (usuarios.length !== 1) {
  return resultado('configuracao_pendente', 'Configure um vínculo único do revisor GitHub com seu usuário Slack no nó 02.', base);
}
return resultado('pronto_para_perguntar', 'Aprovação ALTO elegível.', {
  ...base, usuario_slack_esperado: usuarios[0], team_id: cfg.team_id,
  app_id: cfg.app_id, canal_id: cfg.canal_id,
});

const crypto = require('crypto');
const f = $json.feedback;
const cfg = $json.configuracao_feedback;
if (f?.status !== 'pronto_para_perguntar') throw new Error('Evento não elegível para pergunta.');
const segredo = $env.N8N_SEGREDO_ACOES;
if (!segredo) throw new Error('N8N_SEGREDO_ACOES indisponível.');
if (!Number.isSafeInteger(cfg.prazo_resposta_horas) || cfg.prazo_resposta_horas < 1 || cfg.prazo_resposta_horas > 720) {
  throw new Error('Prazo de resposta deve ser de 1 a 720 horas.');
}
const agora = Math.floor(Date.now() / 1000);
const opcoes = [
  ['regra_conservadora', 'Regra conservadora demais'],
  ['risco_aceito', 'Risco aceito conscientemente'],
  ['falso_positivo', 'Falso positivo'],
];
const contextoBase = {
  v: 1, installation_id: f.installation_id, id_aprovacao: f.id_aprovacao,
  task_run_id: f.task_run_id, revisor_github: f.revisor_github,
  usuario_slack_esperado: f.usuario_slack_esperado,
  team_id: f.team_id, app_id: f.app_id, canal_id: f.canal_id,
  emitido_em: agora, expira_em: agora + cfg.prazo_resposta_horas * 3600,
};
const botoes = opcoes.map(([motivo, rotulo]) => {
  const contexto = Buffer.from(JSON.stringify({ ...contextoBase, feedback_reason: motivo }), 'utf8').toString('base64url');
  const assinatura = crypto.createHmac('sha256', segredo).update('aprova-feedback-v1.' + contexto).digest('hex');
  const value = JSON.stringify({ contexto, assinatura });
  if (value.length > 2000) throw new Error('Contexto excede o limite do botão Slack.');
  return { type: 'button', action_id: 'aprova_feedback_' + motivo,
    text: { type: 'plain_text', text: rotulo }, value };
});
const aviso = cfg.api_feedback_habilitada
  ? 'O motivo só será confirmado após o núcleo validar e persistir o feedback.'
  : 'Integração com a API de feedback ainda pendente. O clique não será salvo em approvals nesta configuração.';
const pergunta = f.revisor_github + ', por que você aprovou a mudança que o gate marcou como ALTO risco?';
return { json: {
  ...$json,
  slack_payload: {
    channel: f.canal_id,
    text: 'aPRova | Motivo da aprovação de ' + f.repositorio + ' #' + f.numero_pr + '. ' + pergunta + ' ' + aviso,
    blocks: [
      { type: 'section', text: { type: 'plain_text',
        text: 'aPRova | Feedback da aprovação\nPR: ' + f.repositorio + ' #' + f.numero_pr +
          '\nhttps://github.com/' + f.repositorio + '/pull/' + f.numero_pr +
          '\nRevisor GitHub: ' + f.revisor_github + '\n\n' + pergunta } },
      { type: 'section', text: { type: 'mrkdwn', text: '<@' + f.usuario_slack_esperado + '> selecione um dos três motivos abaixo.' } },
      { type: 'actions', block_id: 'aprova_feedback_v1', elements: botoes },
      { type: 'context', elements: [{ type: 'plain_text', text: aviso }] },
    ],
  },
} };

const origem = $('07 | Preparar Pergunta e Botões').first().json;
const ts = $json.message?.ts || $json.ts || $json.message_timestamp;
if ($json.ok !== true || $json.channel !== origem.feedback.canal_id || typeof ts !== 'string' || !ts) {
  throw new Error('Slack não confirmou a publicação da pergunta. Confira o canal antes de reenviar.');
}
return { json: { feedback: { ...origem.feedback,
  status: 'pergunta_publicada', mensagem_slack_ts: ts,
  motivo: 'Pergunta publicada; ainda não existe feedback registrado no núcleo.',
} } };
